import{x as s}from"./index-DEP39t22.js";const r={async getDashboard(){return(await s.get("/dosen/dashboard")).data},async getBimbinganList(n={}){return(await s.get("/dosen/bimbingan",{params:n})).data},async getMentorSemproList(n={}){return(await s.get("/dosen/mentor-sempro",{params:n})).data},async getBimbinganDetail(n){return(await s.get(`/dosen/bimbingan/${n}`)).data},async getBimbinganLogs(n){return(await s.get(`/dosen/bimbingan/${n}/logs`)).data},async updateBimbinganStatus(n,e,a=null){return(await s.put(`/dosen/bimbingan/log/${n}/status`,{status:e,catatan_dosen:a})).data},async approveBimbingan(n,e=null){return this.updateBimbinganStatus(n,"approved",e)},async requestRevision(n,e){return this.updateBimbinganStatus(n,"revision",e)},async rejectBimbingan(n,e){return this.updateBimbinganStatus(n,"rejected",e)},async bulkUpdateBimbinganStatus(n,e){return(await s.put("/dosen/bimbingan/log/bulk-status",{ids:n,status:e})).data},async downloadOfficialPdf(n,e){return s.get(`/dosen/bimbingan/${n}/pdf/${e}`,{responseType:"blob"})},async getJadwal(n={}){return(await s.get("/dosen/jadwal",{params:n})).data},async getSeminarDetail(n){return(await s.get(`/dosen/seminar/${n}`)).data},async submitNilai(n,e){return(await s.put(`/dosen/seminar/${n}/nilai`,e)).data},async getUjianRequests(){return(await s.get("/dosen/ujian-requests")).data},async respondUjianRequest(n,e,a=null){return(await s.post(`/dosen/ujian-requests/${n}/respond`,{action:e,alasan:a})).data},async getTanggalPenting(){return(await s.get("/public/tanggal-penting")).data},async getPanduan(){return(await s.get("/public/panduan/dosen")).data},async downloadPanduan(n){return await s.get(`/public/panduan/${n}/download`,{responseType:"blob"})},async getModuleSettings(){return(await s.get("/dosen/module-settings")).data}};export{r as d};
